#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory not found at ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Apply migrations by logging each migration file
 */
function applyMigrations() {
  console.log('Starting database migrations...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/ directory');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((filename, index) => {
    const filepath = path.join(MIGRATIONS_DIR, filename);

    try {
      // Check if file is readable
      fs.accessSync(filepath, fs.constants.R_OK);

      console.log(`${index + 1}. ${filename}`);

      // Optionally log file size
      const stats = fs.statSync(filepath);
      console.log(`   Size: ${stats.size} bytes\n`);
    } catch (error) {
      console.error(`Error accessing file ${filename}: ${error.message}\n`);
    }
  });

  console.log('Migration plan complete.');
  console.log(`Total migrations to apply: ${migrationFiles.length}`);
}

// Run the migration script
applyMigrations();

CREATE TABLE users (
  id INT PRIMARY KEY AUTO_INCREMENT,
  username VARCHAR(255) UNIQUE NOT NULL,
  email VARCHAR(255) UNIQUE NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

