/**
 * Read and parse .env.test file
 * @returns {Object} Environment variables as key-value pairs
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.error(`Error: .env.test file not found at ${ENV_FILE}`);
      return {};
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        return;
      }

      const [key, ...valueParts] = trimmedLine.split('=');
      const value = valueParts.join('=').trim();

      if (key) {
        envVars[key.trim()] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading .env.test file: ${error.message}`);
    return {};
  }
}

/**
 * Get database connection string from environment
 * @param {Object} envVars - Environment variables
 * @returns {string|null} DATABASE_URL or null if not found
 */
function getDatabaseUrl(envVars) {
  return envVars.DATABASE_URL || null;
}

/**
 * Log connection status
 * @param {string|null} databaseUrl - The database connection string
 * @returns {boolean} True if connection string was found
 */
function logConnectionStatus(databaseUrl) {
  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    return false;
  }

  console.log('✓ Successfully resolved DATABASE_URL');
  console.log(`✓ Connected to database: ${maskDatabaseUrl(databaseUrl)}\n`);
  return true;
}

/**
 * Mask sensitive information in database URL
 * @param {string} url - The database URL
 * @returns {string} Masked URL for logging
 */
function maskDatabaseUrl(url) {
  try {
    const urlObj = new URL(url);
    if (urlObj.password) {
      urlObj.password = '****';
    }
    return urlObj.toString();
  } catch (error) {
    // If URL parsing fails, return a generic masked version
    return url.replace(/:[^:@]+@/, ':****@');
  }
}

