/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

function runMigrations() {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Migrations directory not found at ${migrationsDir}`);
    process.exit(1);
  }

  try {
    // Read all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in ./migrations/');
      return;
    }

    console.log(`Found ${sqlFiles.length} migration(s):\n`);

    // Log each migration file that would be applied
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log('\n--- Migration Summary ---');
    console.log(`Total migrations to apply: ${sqlFiles.length}`);

    // Here you would typically apply each migration
    // For now, we're just logging what would be applied
    console.log('Ready to execute migrations in order.');

  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

// Run migrations if this script is executed directly
if (require.main === module) {
  runMigrations();
}

module.exports = { runMigrations };

