}

/**
 * Mask sensitive information in connection string
 * @param {string} url Connection string
 * @returns {string} Masked connection string
 */
function maskConnectionString(url) {
  // Mask password in connection strings like: postgresql://user:password@host/db
  return url.replace(/:([^@]+)@/, ':****@');
}

/**
 * Get all SQL files from the migrations directory, sorted numerically
 * @returns {string[]} Array of migration filenames sorted in order
 */

