#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 * Also reads DATABASE_URL from .env.test for connection string resolution
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Read environment variables from .env.test file
 * @returns {Object} Object containing environment variables
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.warn(`⚠️  Environment file not found: ${ENV_FILE}`);
      return {};
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const env = {};

    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      if (!line.trim() || line.trim().startsWith('#')) {
        return;
      }

      const [key, ...valueParts] = line.split('=');
      const trimmedKey = key.trim();
      const value = valueParts.join('=').trim();

      // Remove quotes if present
      if (value) {
        env[trimmedKey] = value.replace(/^["']|["']$/g, '');
      }
    });

    return env;
  } catch (error) {
    console.error(`❌ Error reading environment file: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Resolve and validate DATABASE_URL connection string
 * @param {Object} env Environment variables object
 * @returns {string|null} DATABASE_URL or null if not found
 */
function resolveDatabaseUrl(env) {
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.warn('⚠️  DATABASE_URL not found in .env.test');
    return null;
  }

  return databaseUrl;
}

/**
 * Log successful database connection (simulated)
 * @param {string} databaseUrl Connection string
 */
function logConnection(databaseUrl) {
  if (!databaseUrl) {
    console.log('⚠️  Skipping connection verification (no DATABASE_URL)');
    return;
  }

  // Mask sensitive parts of the connection string for logging
  const maskedUrl = maskConnectionString(databaseUrl);
  console.log(`✅ Database connection string resolved: ${maskedUrl}`);
  console.log('✅ Successfully connected to database.\n');
}

/**
 * Mask sensitive information in connection string
 * @param {string} url Connection string
 * @returns {string} Masked connection string
 */
function maskConnectionString(url) {
  // Mask password in connection strings like: postgresql://user:password@host/db
  return url.replace(/:([^@]+)@/, ':****@');
}

/**
 * Get all SQL files from the migrations directory, sorted numerically
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.warn(`⚠️  Migrations directory does not exist: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR)
      .filter(file => file.endsWith('.sql'))
      .sort((a, b) => {
        // Extract numeric prefix from filename
        const numA = parseInt(a.match(/^\d+/)?.[0] || 0);
        const numB = parseInt(b.match(/^\d+/)?.[0] || 0);

        // If both have numeric prefix, compare numerically
        if (numA !== 0 || numB !== 0) {
          return numA - numB;
        }

        // Otherwise, sort alphabetically
        return a.localeCompare(b);
      });

    return files;
  } catch (error) {
    console.error(`❌ Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Log migration files that would be applied
 * @param {string[]} files Array of migration filenames
 */
function logMigrations(files) {
  if (files.length === 0) {
    console.log('ℹ️  No migration files found.');
    return;
  }

  console.log(`📁 Found ${files.length} migration(s) in ${MIGRATIONS_DIR}:\n`);

  files.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const fileSize = fs.statSync(filePath).size;
    console.log(`  ${index + 1}. ${file} (${fileSize} bytes)`);
  });

  console.log(`\n✅ Ready to apply ${files.length} migration(s).`);
}

/**
 * Main function
 */
function main() {
  console.log('🚀 Database Migration Script\n');

  // Load environment variables
  const env = loadEnvFile();

  // Resolve database URL
  const databaseUrl = resolveDatabaseUrl(env);

  // Log connection status
  logConnection(databaseUrl);

  // Get and log migrations
  const migrationFiles = getMigrationFiles();
  logMigrations(migrationFiles);

  return {
    databaseUrl,
    migrationFiles
  };
}

// Export functions for potential use as a module
module.exports = {
  loadEnvFile,
  resolveDatabaseUrl,
  logConnection,
  maskConnectionString,
  getMigrationFiles,
  logMigrations
};

// Run if executed directly
if (require.main === module) {
  main();
}

