const fs = require('fs');
const path = require('path');

// Directory containing migration files
const migrationsDir = './migrations';

/**
 * Reads .env.test file and parses key-value pairs
 */
function loadEnvTest() {
  const envPath = '.env.test';

  if (!fs.existsSync(envPath)) {
    console.error(`Error: .env.test file not found: ${envPath}`);
    process.exit(1);
  }

  const envContent = fs.readFileSync(envPath, 'utf8');
  const env = {};

  envContent.split('\n').forEach(line => {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, value] = trimmed.split('=');
      if (key && value) {
        env[key.trim()] = value.trim();
      }
    }
  });

  return env;
}

/**
 * Resolves database connection string from environment
 */
function getConnectionString() {
  const env = loadEnvTest();
  const connectionString = env.DATABASE_URL;

  if (!connectionString) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  return connectionString;
}

/**
 * Simulates connecting to the database
