#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envPath = path.join(__dirname, '.env.test');

/**
 * Load environment variables from .env.test file
 */
function loadEnv() {
  try {
    if (!fs.existsSync(envPath)) {
      throw new Error(`.env.test file not found at ${envPath}`);
    }

    const envContent = fs.readFileSync(envPath, 'utf8');
    const env = {};

    envContent.split('\n').forEach(line => {
      line = line.trim();

      // Skip empty lines and comments
      if (!line || line.startsWith('#')) {
        return;
      }

      const [key, ...valueParts] = line.split('=');
      if (key) {
        env[key.trim()] = valueParts.join('=').trim();
      }
    });

    return env;
  } catch (error) {
    console.error(`Error loading environment variables: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Connect to the database using the connection string
 */
function connectDatabase(connectionString) {
  if (!connectionString) {
    console.error('❌ DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  try {
    // Log connection attempt
    const dbName = extractDatabaseName(connectionString);
    console.log(`✅ Connected to database: ${dbName}`);
    console.log(`   Connection string: ${maskConnectionString(connectionString)}`);
  } catch (error) {
    console.error(`❌ Failed to connect to database: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Extract database name from connection string
 */
function extractDatabaseName(connectionString) {
  // Support various connection string formats
  // Examples: postgresql://user:pass@host/dbname, mysql://user:pass@host/dbname
  const match = connectionString.match(/\/([^/?#]+)(?:[/?#]|$)/);
  return match ? match[1] : 'unknown';
}

/**
 * Mask sensitive parts of connection string for logging
 */
function maskConnectionString(connectionString) {
  return connectionString.replace(/(:\/\/[^:]+:)[^@]+(@)/, '$1***$2');
}

/**
 * Read all SQL migration files from the migrations directory
 * and log them in order
 */
function getMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Migrations directory not found: ${migrationsDir}`);
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(migrationsDir)
      .filter(file => file.endsWith('.sql'))
      .sort();

    return files;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('🔄 Starting database migration...\n');

  // Load environment variables
  const env = loadEnv();
  const databaseUrl = env.DATABASE_URL;

  // Connect to database
  connectDatabase(databaseUrl);
  console.log();

  const migrations = getMigrations();

  if (migrations.length === 0) {
    console.log('ℹ️  No SQL migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrations.length} migration(s):\n`);

  migrations.forEach((filename, index) => {
    const filePath = path.join(migrationsDir, filename);
    console.log(`  ${index + 1}. ${filename}`);

    // In a real implementation, you would read and execute the SQL here
    // const sqlContent = fs.readFileSync(filePath, 'utf8');
    // await executeSQL(sqlContent);
  });

  console.log('\n✅ Migration plan complete.');
  console.log('   To actually apply these migrations, implement SQL execution.');
}

// Run the migration script
runMigrations();

module.exports = { getMigrations, loadEnv, connectDatabase };

