      // Skip empty lines and comments
      if (!trimmed || trimmed.startsWith('#')) {
        continue;
      }

      // Look for DATABASE_URL
      if (trimmed.startsWith('DATABASE_URL')) {
        const match = trimmed.match(/DATABASE_URL\s*=\s*(.+)/);
        if (match && match[1]) {
          return match[1].trim().replace(/^["']|["']$/g, ''); // Remove surrounding quotes if present
        }
      }
    }

    throw new Error('DATABASE_URL not found in .env.test');
  } catch (error) {
    console.error(`Error loading database URL: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Simulates database connection (logs success message)
 * @param {string} connectionString - The database connection string
 */
function connectToDatabase(connectionString) {
  // Mask the connection string for logging (hide credentials)
  const maskedUrl = connectionString.replace(/(:\/\/[^:]+:)[^@]+(@)/, '$1****$2');
  console.log(`✓ Connected successfully to database: ${maskedUrl}`);
}

/**
 * Reads SQL migration files from the migrations directory
 * and logs each filename in order
 */
async function migrate() {
