 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Gets all SQL migration files from the migrations directory
 * @returns {string[]} Array of SQL filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.warn(`Migrations directory does not exist: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Validates migration file naming convention (optional)
 * Expects format like: YYYY_MM_DD_HHmmss_description.sql or sequential numbering
 * @param {string} filename - The migration filename
 * @returns {boolean} True if filename matches expected pattern
 */
function isValidMigrationFilename(filename) {
  // Allow timestamps or sequential numbering like: 001_init.sql, 002_create_users.sql
  // or timestamps like: 20240101_120000_init.sql
  const validPattern = /^(\d{3,}|20\d{2}_\d{2}_\d{2}_\d{6})_[a-z0-9_]+\.sql$/i;
  return validPattern.test(filename);
}

/**
 * Applies migrations by logging which files would be executed
 */
function applyMigrations() {
  console.log('='.repeat(60));
