  });

  console.log('\n' + '='.repeat(60));
  console.log(`\nMigrations to apply: ${migrationFiles.length}`);
  console.log('Status: Ready for execution (dry run completed)');
  console.log('\n' + '='.repeat(60) + '\n');

  return migrationFiles;
}

/**
 * Main execution
 */
function main() {
  try {
    applyMigrations();
  } catch (error) {
    console.error(`Fatal error: ${error.message}`);
    process.exit(1);
  }
}

// Run the migration script
if (require.main === module) {
  main();
}

module.exports = { getMigrationFiles, applyMigrations, isValidMigrationFilename };

