/**
 * Parses a .env file and returns key-value pairs
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Environment variables as key-value pairs
 */
function parseEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      console.warn(`Environment file not found: ${filePath}`);
      return {};
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const env = {};

    content.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE format
      const [key, ...valueParts] = line.split('=');
      const trimmedKey = key.trim();
      const value = valueParts.join('=').trim();

      if (trimmedKey) {
        // Remove surrounding quotes if present
        const cleanValue = value.replace(/^["']|["']$/g, '');
        env[trimmedKey] = cleanValue;
      }
    });

    return env;
  } catch (error) {
    console.error(`Error parsing environment file: ${error.message}`);
    return {};
  }
}

/**
 * Resolves and validates the database connection string
 * @returns {string|null} The DATABASE_URL or null if not found
