 * Resolves DATABASE_URL from .env.test file
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Resolve and validate the database connection string
 * @returns {string} The DATABASE_URL from environment
 * @throws {Error} If DATABASE_URL is not set
 */
function resolveConnectionString() {
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    throw new Error(
      'DATABASE_URL not found in .env.test. Please ensure .env.test file exists and contains DATABASE_URL.'
    );
  }

  return databaseUrl;
}

/**
 * Get all SQL migration files from the migrations directory
 * Sorts them alphabetically to ensure consistent order
 * @returns {string[]} Array of migration filenames
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.warn(`Migrations directory does not exist: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files and sort alphabetically
    const sqlFiles = files
      .filter(file => path.extname(file) === '.sql')
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Main migration function
 * Resolves database connection and logs each migration file that would be applied
 */
function migrate() {
  console.log('Database Migration Script');
  console.log('========================\n');

  // Resolve and log database connection
  try {
    const connectionString = resolveConnectionString();
    console.log('✓ Connected to database successfully');
