  if (migrations.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s) to apply:\n`);

  migrations.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log('\n========================');
  console.log(`Ready to apply ${migrations.length} migration(s).`);
}

