#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 * Resolves database connection from .env.test
 */

// Define the migrations directory
const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');

/**
 * Parse .env.test file and return environment variables as an object
 */
function loadEnvTest() {
  try {
    if (!fs.existsSync(envTestPath)) {
      throw new Error(`File not found: ${envTestPath}`);
    }

    const envContent = fs.readFileSync(envTestPath, 'utf-8');
    const env = {};

    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      const trimmedLine = line.trim();
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE format
      const [key, ...valueParts] = trimmedLine.split('=');
      const value = valueParts.join('=').trim();

      if (key && value) {
        env[key.trim()] = value;
      }
    });

    return env;
  } catch (error) {
    console.error(`Error loading .env.test: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Resolve database connection string
 */
function resolveDatabase() {
  const env = loadEnvTest();

  if (!env.DATABASE_URL) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  return env.DATABASE_URL;
}

/**
 * Reads migration files from the migrations directory and logs them in order
 */
async function runMigrations() {
  try {
    // Resolve database connection
    console.log('Resolving database connection...');
    const databaseUrl = resolveDatabase();
    console.log(`✓ Connected successfully to: ${databaseUrl}\n`);

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Error: Migrations directory not found at ${migrationsDir}`);
      process.exit(1);
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log(`Found ${sqlFiles.length} migration file(s):\n`);

    // Log each migration file in order
    sqlFiles.forEach((filename, index) => {
      const filePath = path.join(migrationsDir, filename);
      const stats = fs.statSync(filePath);
      const fileSize = stats.size;

      console.log(`${index + 1}. ${filename} (${fileSize} bytes)`);

      // Optional: Log the file content (commented out for brevity)
      // const content = fs.readFileSync(filePath, 'utf-8');
      // console.log(`   Content: ${content.substring(0, 100)}...`);
    });

    console.log(`\nTotal migrations to apply: ${sqlFiles.length}`);
  } catch (error) {
    console.error('Error running migrations:', error.message);
    process.exit(1);
  }
}

// Run migrations if executed directly
if (require.main === module) {
  runMigrations();
}

// Export for use as a module
module.exports = { runMigrations, resolveDatabase, loadEnvTest };
